using namespace hanmo::resident;
namespace {
// 即使NDEBUG也保留测试失败。
void check(bool good,const char* message){if(!good)throw std::runtime_error(message);}
// 每次破坏只修改测试自己的JSON值。
BoundaryValue& field(BoundaryValue& v,const char* key){auto* p=v.find(key);check(p,"fixture field");return *p;}
// 精确夹具仍由唯一数值叶构造，不能使用double近似。
WorldMoment at(Integer tick,const char* n="0",const char* d="1"){auto f=normalize_fraction(n,d);check(f.ok,"fraction");return {tick,f.value};}
// 身份全部字段及模块原序均需往返保留。
CatalogIdentity identity(){return {"content","1","digest","rules","schema",StableId{"pack"},{{"z","2"},{"a","1"}},"artifact"};}
// 报告覆盖原fact全部可选观察，测试值只检codec不声称真实业务来源。
DynamicSocialState sample(Integer version){DynamicSocialState s;s.version=version;s.last_collected_tick=9;s.time2.emplace();
    Report r;r.id="report-z";r.fact_id="fact-z";r.payload_kind="supply";r.origin_subject={SubjectKind::actor,"a"};r.observation_tick=8;r.visibility_scope=ReportVisibility::local_public;r.valid_until_tick=20;r.reliability_kind=ReportReliability::official;
    r.observation={"fact-z","supply","1",8,{"cause-b","cause-a"},{"affair"},{{{SubjectKind::actor,"a"},"observer"}},SupplyObservation{"source","org","site","inventory","item","fact-z",9,4,3},ObligationObservation{"obligation","principal","beneficiary","fact-z",10,7,2,5,"arrear"},"subject","shortage",true};
    check(s.reports.insert(r.id,r),"report insert");r.id="report-a";r.valid_until_tick.reset();check(s.reports.insert(r.id,r),"second report");
    PendingMessage m;m.id="message-z";m.report_id="report-z";m.sender={SubjectKind::actor,"a"};m.receiver={SubjectKind::organization,"o"};m.channel="public";m.created_tick=8;m.due_tick=9;m.status=MessageStatus::delivered;if(version==4)m.local_place_id="place";check(s.pending_messages.insert(m.id,m),"message insert");m.id="message-a";m.status=MessageStatus::pending;m.local_place_id.reset();m.address_binding=SocialS3AddressBinding{{"politics","communication_link","link"}};m.receiver={};check(s.pending_messages.insert(m.id,m),"address insert");
    KnownReport k{{SubjectKind::organization,"o"},"report-z",StableId{"message-z"},9,{SubjectKind::actor,"a"}};OrderedTable<KnownReport> known;known.insert(k.report_id,k);k.report_id="report-a";k.source_message_id.reset();known.insert(k.report_id,k);s.known_reports.insert("organization:o",std::move(known));
    auto& t=*s.time2;t.source_time_bindings.insert("z",{ReportObservationKey{"report-z"},SocialLegacyBoundary{8,identity()},{"common","fact","fact-z"}});t.source_time_bindings.insert("a",{MessageCreatedKey{"message-z"},SocialExactMoment{at(8,"9007199254740993","9007199254740995")},{"social","message_created","message-z"}});t.source_time_bindings.insert("b",{MessageDeliveredKey{"message-z"},SocialExactSource{{{"social","social_period_close","period"},1}},{"social","message_delivered","message-z"}});t.source_time_bindings.insert("k",{SocialKnowledgeKey{{SubjectKind::organization,"o"},"report-z"},SocialExactMoment{at(9)},{"social","message_delivered","message-z"}});
    SocialMessageExecutionBinding e;e.message_id="message-z";e.source_binding=SocialLegacyChannel{"legacy-profile"};e.actual_delivery_ref=SourceRef{"social","social_period_close","period"};e.actual_dossier_access_ref=SourceRef{"politics","access","access"};e.actual_knowledge_keys={{{SubjectKind::organization,"o"},"report-z"},{{SubjectKind::actor,"b"},"report-z"}};e.channel_rule_ref={identity(),"channel"};t.message_execution_bindings.insert("z",e);e.message_id="message-a";e.source_binding=SocialS3BusinessLink{{"politics","communication_link","link"}};e.actual_delivery_ref.reset();e.actual_dossier_access_ref.reset();e.actual_knowledge_keys.clear();t.message_execution_bindings.insert("a",e);t.collection_cursor={StableId{"fact-z"},at(9,"1","3")};return s;}
// 保存与恢复都调用真实公开visitor，finish检查尾随字节。
template<class T,class F> CodecVisitor::Buffer binary(T value,F visit){CodecVisitor::Buffer b;CodecVisitor c(b);auto r=visit(c,value);check(r.ok&&c.finish().ok,"binary write");return b;}
// 失败仅返回false；调用者已有对象应由公开visitor保护。
template<class T,class F> bool restore(const CodecVisitor::Buffer& b,T& value,F visit){CodecVisitor c(b);return visit(c,value).ok&&c.finish().ok;}
// 两端交叉往返需值、字典序和binary字节全部一致。
void roundtrips(){for(Integer version:{3,4}){auto s=sample(version);auto j=encode_dynamic_social_time2(s);check(j.ok,"social JSON encode");const auto& root=*j.value.as<BoundaryValue::Dict>();check(root.size()==10,"exact ten roots");const char* names[]={"version","last_collected_tick","reports","pending_messages","known_reports","source_time_bindings","message_execution_bindings","propagation_decisions","propagation_cooldowns","collection_cursor"};for(std::size_t i=0;i<10;++i)check(root[i].first==names[i],"root order");auto text=render_boundary_json(j.value);check(text.ok,"JSON render");auto parsed=parse_boundary_json(text.value);check(parsed.ok,"JSON parse");auto d=decode_dynamic_social_time2(parsed.value);check(d.ok,"social JSON decode");auto b=binary(d.value,visit_dynamic_social_time2_checkpoint);DynamicSocialState restored;check(restore(b,restored,visit_dynamic_social_time2_checkpoint),"social binary decode");auto again=encode_dynamic_social_time2(restored);check(again.ok&&compare_boundary(j.value,again.value).exact(),"JSON binary paired");check(b==binary(restored,visit_dynamic_social_time2_checkpoint),"binary stable");check(restored.time2->source_time_bindings.rows()[0].first=="z"&&restored.time2->source_time_bindings.rows()[1].first=="a","ordered tables unsorted");
        s.pending_messages=OrderedTable<PendingMessage>{};s.time2.reset();s.version=version-2;auto old=encode_dynamic_social(s);auto legacy=decode_dynamic_social(old);check(legacy.ok,"legacy JSON unchanged");auto old_bytes=binary(s,visit_dynamic_social_checkpoint);DynamicSocialState old_read;check(restore(old_bytes,old_read,visit_dynamic_social_checkpoint)&&old_bytes==binary(old_read,visit_dynamic_social_checkpoint),"legacy binary unchanged");check(compare_boundary(field(old,"reports"),field(j.value,"reports")).exact()&&compare_boundary(field(old,"known_reports"),field(j.value,"known_reports")).exact(),"legacy Report and Known JSON bytes");
        DynamicSocialState empty;empty.version=version;empty.time2.emplace();auto ej=encode_dynamic_social_time2(empty);check(ej.ok&&ej.value.as<BoundaryValue::Dict>()->size()==10&&decode_dynamic_social_time2(ej.value).ok,"empty ten roots");check(field(ej.value,"propagation_decisions").as<BoundaryValue::Dict>()&&field(ej.value,"propagation_cooldowns").as<BoundaryValue::Dict>(),"empty table shape");}}
// 所有有限联合、根形状、重复键与未选表必须明确拒绝。
void rejections(){auto reject=[](BoundaryValue v){check(!decode_dynamic_social_time2(v).ok,"malformed JSON rejected");};auto fresh=[](){auto j=encode_dynamic_social_time2(sample(4));check(j.ok,"fresh JSON");return std::move(j.value);};
    auto v=fresh();v.as<BoundaryValue::Dict>()->pop_back();reject(std::move(v));v=fresh();v.as<BoundaryValue::Dict>()->emplace_back("extra",Integer{1});reject(std::move(v));v=fresh();v.as<BoundaryValue::Dict>()->push_back(v.as<BoundaryValue::Dict>()->front());reject(std::move(v));v=fresh();std::swap((*v.as<BoundaryValue::Dict>())[0],(*v.as<BoundaryValue::Dict>())[1]);reject(std::move(v));
    for(Integer bad:{1,2,5,-1}){v=fresh();field(v,"version")=BoundaryValue{bad};reject(std::move(v));}
    for(const char* table:{"reports","pending_messages","known_reports","source_time_bindings","message_execution_bindings"}){v=fresh();auto& rows=*field(v,table).as<BoundaryValue::Dict>();rows.push_back(rows.front());reject(std::move(v));}
    for(const char* name:{"key","time_source"}){v=fresh();auto& row=field(v,"source_time_bindings").as<BoundaryValue::Dict>()->front().second;field(field(row,name),"tag").data=Integer{99};reject(std::move(v));}
    v=fresh();auto& message=field(v,"pending_messages").as<BoundaryValue::Dict>()->front().second;field(field(message,"receiver"),"tag").data=Integer{2};reject(std::move(v));
    v=fresh();auto& execution=field(v,"message_execution_bindings").as<BoundaryValue::Dict>()->front().second;field(field(execution,"source_binding"),"tag").data=Integer{-1};reject(std::move(v));
    for(const char* table:{"propagation_decisions","propagation_cooldowns"}){v=fresh();field(v,table).as<BoundaryValue::Dict>()->emplace_back("unselected",BoundaryValue::Dict{});auto bad=decode_dynamic_social_time2(v);check(!bad.ok&&bad.error.kind==ErrorKind::unsupported_capability,"nonempty propagation unsupported");v=fresh();field(v,table).data=BoundaryValue::Array{};reject(std::move(v));}
    v=fresh();auto& source=field(field(v,"source_time_bindings").as<BoundaryValue::Dict>()->at(2).second,"time_source");field(field(source,"original_timed_source_ref"),"source_schema").data=Integer{0};reject(std::move(v));
    v=fresh();auto& exact=field(field(field(v,"source_time_bindings").as<BoundaryValue::Dict>()->at(1).second,"time_source"),"moment");field(field(exact,"sub_half_day"),"numerator")="01";reject(std::move(v));
    v=fresh();auto& bindings=*field(v,"source_time_bindings").as<BoundaryValue::Dict>();bindings.front().second.as<BoundaryValue::Dict>()->pop_back();reject(std::move(v));
    v=fresh();auto& report=field(v,"reports").as<BoundaryValue::Dict>()->front().second;field(report,"visibility_scope").data=Integer{99};reject(std::move(v));
    v=fresh();auto& modules=*field(field(field(field(v,"message_execution_bindings").as<BoundaryValue::Dict>()->front().second,"channel_rule_ref"),"catalog_identity"),"module_versions").as<BoundaryValue::Array>();modules.push_back(modules.front());reject(std::move(v));
    auto bad_enum=sample(4);bad_enum.reports.rows().front().second.visibility_scope=static_cast<ReportVisibility>(99);auto rejected_enum=encode_dynamic_social_time2(bad_enum);check(!rejected_enum.ok&&rejected_enum.error.original.code=="InvalidDynamicEnum","JSON encode preserves original enum error");CodecVisitor::Buffer invalid_bytes;CodecVisitor invalid_writer(invalid_bytes);auto rejected_binary=visit_dynamic_social_time2_checkpoint(invalid_writer,bad_enum);check(!rejected_binary.ok&&rejected_binary.error.original.code=="InvalidDynamicEnum","binary encode preserves original enum error");
    auto s=sample(3);s.pending_messages.rows().front().second.local_place_id="illegal";check(!encode_dynamic_social_time2(s).ok,"base3 rejects local place");s=sample(4);s.time2.reset();check(!encode_dynamic_social_time2(s).ok,"missing time2 rejected");s=sample(4);s.time2->propagation_decisions.insert("marker",{});auto bad=encode_dynamic_social_time2(s);check(!bad.ok&&bad.error.kind==ErrorKind::unsupported_capability,"typed nonempty propagation unsupported");
}

// 原1/2前五根字节除新receiver.tag与物理version外应完全相同。
void legacy_binary_prefix(){for(Integer version:{3,4}){auto s=sample(version);s.pending_messages.erase("message-a");auto newer=binary(s,visit_dynamic_social_time2_checkpoint);s.time2.reset();s.version-=2;const auto old=binary(s,visit_dynamic_social_checkpoint);CodecVisitor::Buffer tag;CodecVisitor writer(tag);Integer zero=0;check(writer.field("tag",zero).ok&&writer.finish().ok,"tag bytes");auto found=std::search(newer.begin(),newer.end(),tag.begin(),tag.end());check(found!=newer.end(),"receiver tag exists");newer.erase(found,found+tag.size());CodecVisitor::Buffer version_field;CodecVisitor vw(version_field);check(vw.field("version",s.version).ok,"version bytes");std::copy(version_field.begin(),version_field.end(),newer.begin());check(newer.size()>old.size()&&std::equal(old.begin(),old.end(),newer.begin()),"legacy full prefix bytes preserved");}}
// 已编码字段的原始模式只用于破坏测试，不成为另一生产codec。
CodecVisitor::Buffer integer_field(const char* name,Integer value){CodecVisitor::Buffer b;CodecVisitor c(b);check(c.field(name,value).ok,"integer field fixture");return b;}
// tag逐个破坏、全截断、尾随和重复外键都必须在真实visitor拒绝。
void binary_rejections(){const auto s=sample(4);const auto b=binary(s,visit_dynamic_social_time2_checkpoint);DynamicSocialState target=sample(3);const auto before=encode_dynamic_social_time2(target);check(before.ok,"failure target");
    for(std::size_t n=0;n<b.size();++n){CodecVisitor::Buffer cut(b.begin(),b.begin()+n);check(!restore(cut,target,visit_dynamic_social_time2_checkpoint),"social binary truncation");}
    auto after=encode_dynamic_social_time2(target);check(after.ok&&compare_boundary(before.value,after.value).exact(),"truncation keeps target");auto tail=b;tail.push_back(0);check(!restore(tail,target,visit_dynamic_social_time2_checkpoint),"social binary trailing bytes");auto corrupt=b;corrupt[0]=255;check(!restore(corrupt,target,visit_dynamic_social_time2_checkpoint),"social binary unknown type");
    std::size_t mutated=0;for(Integer tag=0;tag<=3;++tag){const auto pattern=integer_field("tag",tag);auto start=b.begin();while(start!=b.end()){auto it=std::search(start,b.end(),pattern.begin(),pattern.end());if(it==b.end())break;corrupt=b;corrupt[std::size_t(it-b.begin())+pattern.size()-8]=99;check(!restore(corrupt,target,visit_dynamic_social_time2_checkpoint),"every binary union tag rejected");++mutated;start=it+pattern.size();}}check(mutated==12,"all finite union tags covered");
    const std::string table_name="source_time_bindings";auto begin=std::search(b.begin(),b.end(),table_name.begin(),table_name.end());check(begin!=b.end(),"source table bytes");CodecVisitor::Buffer key;CodecVisitor kw(key);StableId key_value="a";check(kw.field("key",key_value).ok,"key fixture");auto at_key=std::search(begin,b.end(),key.begin(),key.end());check(at_key!=b.end(),"second source key bytes");corrupt=b;corrupt[std::size_t(at_key-b.begin())+key.size()-1]='z';check(!restore(corrupt,target,visit_dynamic_social_time2_checkpoint),"binary duplicate source key");
    auto duplicate=s;duplicate.time2->source_time_bindings.rows().push_back(duplicate.time2->source_time_bindings.rows().front());CodecVisitor::Buffer ignored;CodecVisitor duplicate_writer(ignored);check(!visit_dynamic_social_time2_checkpoint(duplicate_writer,duplicate).ok,"typed duplicate source key write rejected");
    for(const char* name:{"propagation_decisions","propagation_cooldowns"}){auto it=std::search(b.begin(),b.end(),name,name+std::char_traits<char>::length(name));check(it!=b.end(),"empty propagation header");auto offset=std::size_t(it-b.begin())+std::char_traits<char>::length(name);corrupt=b;corrupt[offset]=1;CodecVisitor::Buffer row;CodecVisitor rw(row);check(rw.object("entry",[&](auto& c){StableId key="marker";return c.field("key",key);}).ok,"marker entry bytes");corrupt.insert(corrupt.begin()+offset+8,row.begin(),row.end());CodecVisitor reader(static_cast<const CodecVisitor::Buffer&>(corrupt));auto bad=visit_dynamic_social_time2_checkpoint(reader,target);check(!bad.ok&&bad.error.kind==ErrorKind::unsupported_capability,"binary nonempty propagation unsupported");}
}
// 期间夹具涵盖空集合及非字典排序的真实插入序，不构造第二消息状态。
SocialPeriodSources period_sample(){SocialPeriodSources p;p.openings.insert("period-z",{"period-z",at(8),9,{"message-z","message-a"},identity(),social_due_provider_id,1});p.closures.insert("period-z",{"period-z",at(9),{"message-z","message-a"}});p.openings.insert("period-a",{"period-a",at(9),10,{},identity(),social_due_provider_id,1});return p;}
// JSON→binary→JSON和反向byte稳定；两根完整，引用顺序没有被排序。
void period_roundtrips(){auto p=period_sample();auto j=encode_social_period_sources(p);check(j.ok,"period JSON write");const auto& roots=*j.value.as<BoundaryValue::Dict>();check(roots.size()==2&&roots[0].first=="openings"&&roots[1].first=="closures","period exact two roots");auto d=decode_social_period_sources(j.value);check(d.ok,"period JSON read");const auto b=binary(d.value,visit_social_period_sources_checkpoint);SocialPeriodSources out;check(restore(b,out,visit_social_period_sources_checkpoint),"period binary read");auto again=encode_social_period_sources(out);check(again.ok&&compare_boundary(j.value,again.value).exact()&&b==binary(out,visit_social_period_sources_checkpoint),"period paired exact");check(out.openings.rows()[0].first=="period-z"&&out.openings.rows()[1].first=="period-a","period table sequence");check(out.openings.rows()[0].second.due_message_ids==std::vector<StableId>({"message-z","message-a"}),"period list sequence");SocialPeriodSources empty;auto ej=encode_social_period_sources(empty);check(ej.ok&&decode_social_period_sources(ej.value).ok&&ej.value.as<BoundaryValue::Dict>()->size()==2,"period empty shape");check(field(ej.value,"openings").as<BoundaryValue::Dict>()&&field(ej.value,"closures").as<BoundaryValue::Dict>(),"period empty tables");
    CodecVisitor::Buffer embedded;CodecVisitor writer(embedded);auto social=sample(4);check(writer.object("social",[&](auto& c){return visit_dynamic_social_time2_checkpoint(c,social);}).ok,"embedded social");check(writer.object("periods",[&](auto& c){return visit_social_period_sources_checkpoint(c,p);}).ok&&writer.finish().ok,"embedded period");DynamicSocialState rs;SocialPeriodSources rp;CodecVisitor reader(static_cast<const CodecVisitor::Buffer&>(embedded));check(reader.object("social",[&](auto& c){return visit_dynamic_social_time2_checkpoint(c,rs);}).ok&&reader.object("periods",[&](auto& c){return visit_social_period_sources_checkpoint(c,rp);}).ok&&reader.finish().ok,"embedded both restore");}
// 期间损坏不得补造缺表、重复来源或约分修复非规范Moment。
void period_rejections(){auto fresh=[](){auto x=encode_social_period_sources(period_sample());check(x.ok,"period fixture");return std::move(x.value);};auto reject=[](BoundaryValue v){check(!decode_social_period_sources(v).ok,"malformed period rejected");};auto v=fresh();v.as<BoundaryValue::Dict>()->pop_back();reject(std::move(v));v=fresh();v.as<BoundaryValue::Dict>()->emplace_back("version",BoundaryValue{Integer{1}});reject(std::move(v));for(const char* table:{"openings","closures"}){v=fresh();auto& rows=*field(v,table).as<BoundaryValue::Dict>();rows.push_back(rows.front());reject(std::move(v));v=fresh();field(v,table).data=BoundaryValue::Array{};reject(std::move(v));}
    v=fresh();auto& opening=field(v,"openings").as<BoundaryValue::Dict>()->front().second;auto& ids=*field(opening,"due_message_ids").as<BoundaryValue::Array>();ids.push_back(ids.front());reject(std::move(v));v=fresh();auto& fraction=field(field(field(v,"openings").as<BoundaryValue::Dict>()->front().second,"opened_at"),"sub_half_day");field(fraction,"numerator")="2";field(fraction,"denominator")="4";reject(std::move(v));
    const auto b=binary(period_sample(),visit_social_period_sources_checkpoint);auto target=period_sample();const auto before=encode_social_period_sources(target);for(std::size_t n=0;n<b.size();++n){CodecVisitor::Buffer cut(b.begin(),b.begin()+n);check(!restore(cut,target,visit_social_period_sources_checkpoint),"period binary truncation");}auto after=encode_social_period_sources(target);check(before.ok&&after.ok&&compare_boundary(before.value,after.value).exact(),"period failure keeps target");auto tail=b;tail.push_back(0);check(!restore(tail,target,visit_social_period_sources_checkpoint),"period binary trailing");}
} // 正常功能与格式错误验证不包含已暂停的分配故障测试。
int main(){try{roundtrips();rejections();legacy_binary_prefix();binary_rejections();period_roundtrips();period_rejections();std::cout<<"social time2 codec checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
